"""VIHAP (Vietnamese Hierarchical Address Parser): parse and validate Vietnamese addresses."""

from __future__ import annotations

import importlib.metadata
from collections.abc import Iterable, Iterator
from typing import Any

from loguru import logger

from . import reform
from .formatters import AddressFormatter
from .models import (
    AddressTargetFormat,
    AdminValidationResult,
    BatchParsedAddressResult,
    ParsedAddress,
    ParsedStreet,
    ParserConfig,
    ShortAddress,
    TranslationResult,
)
from .parsers.hierarchical_parser import (
    HierarchicalAddressParser as HierarchicalAddressParser,
)
from .parsers.hierarchical_parser import (
    get_default_parser as _get_default_parser,
)
from .short_parser import parse_short

logger.disable("vihap")

__version__ = "5.5.0"
try:
    _pkg_version = importlib.metadata.version("vihap")
    if _pkg_version.startswith(("5.", "4.", "3.", "2.9", "2.1")):
        __version__ = _pkg_version
except importlib.metadata.PackageNotFoundError:
    pass


def prewarm() -> None:
    """Pre-warm parser singletons and knowledge-base caches for lower request latency."""
    _get_default_parser()


def parse(
    address: str | Any,
    *,
    config: ParserConfig | None = None,
    auto_correct: bool | None = None,
    extract_contact: bool | None = None,
    target_format: AddressTargetFormat | None = None,
    formatter: AddressFormatter | None = None,
) -> ParsedAddress:
    if not isinstance(address, str):
        raise TypeError(f"Expected address as str, got {type(address).__name__}")
    return _get_default_parser().parse(
        address,
        config=config,
        auto_correct=auto_correct,
        extract_contact=extract_contact,
        target_format=target_format,
        formatter=formatter,
    )


def pipe(
    stream: Iterable[str],
    *,
    batch_size: int | None = None,
    **kwargs: Any,
) -> Iterator[ParsedAddress]:
    return _get_default_parser().pipe(stream, batch_size=batch_size, **kwargs)


def parse_batch(
    addresses: Iterable[str],
    **kwargs: Any,
) -> BatchParsedAddressResult:
    return _get_default_parser().parse_batch(addresses, **kwargs)


def validate_admin(
    ward: str,
    district: str | None = None,
    province: str | None = None,
) -> AdminValidationResult:
    return _get_default_parser().validator.validate_admin(
        ward, district=district, province=province
    )


def to_reform(
    address: str | ParsedAddress,
    *,
    target_format: str = "NEW_2TIER",
) -> TranslationResult:
    from .reform.translator import translate_address_to_reform

    parser = _get_default_parser()
    return translate_address_to_reform(
        address,
        parser=parser,
        validator=parser.validator,
        formatter=parser.formatter,
        target_format=target_format,
    )


def parse_street(
    street_text: str | Any,
    *,
    district: str | None = None,
    province: str | None = None,
    extract_contact: bool = True,
) -> ParsedStreet:
    if not isinstance(street_text, str):
        raise TypeError(f"Expected street_text as str, got {type(street_text).__name__}")
    return _get_default_parser().parse_street(
        street_text,
        district=district,
        province=province,
        extract_contact=extract_contact,
    )


__all__ = [
    "parse",
    "parse_batch",

    def record_stage(self, stage_name: str) -> None:
        """Record a completed stage name into the execution trace."""
        self.stages_executed.append(stage_name)

    def record_error(self, stage_name: str, message: str) -> None:
        """Record an error occurred during a stage execution."""
        self.errors.append(f"[{stage_name}] {message}")


StageCallable = Callable[[ParsingContext], StageResult]


class MicroAddressPipeline:
    """Ordered pipeline runner orchestrating micro-address parsing stages."""

    def __init__(
        self,
        stages: Sequence[Any] | None = None,
        *,
        name: str = "MicroAddressPipeline",
    ) -> None:
        self.name = name
        self._stages: list[Any] = list(stages) if stages else []
        self._compiled_stages: list[tuple[Any, str]] = [
            (s, self._resolve_stage_name(s)) for s in self._stages
        ]

    @property
    def stage_count(self) -> int:
        """Number of stages configured in this pipeline."""
        return len(self._stages)

    def add_stage(self, stage: Any) -> MicroAddressPipeline:
        """Append a stage to the pipeline and return self for fluent chaining."""
        self._stages.append(stage)
        self._compiled_stages.append((stage, self._resolve_stage_name(stage)))
        return self

    def _resolve_stage_name(self, stage: Any) -> str:
        if hasattr(stage, "name"):
            return str(stage.name)
        if hasattr(stage, "__name__"):
            return str(stage.__name__)
        return stage.__class__.__name__

    def _invoke_stage(self, stage: Any, context: ParsingContext) -> StageResult:
        """Invoke a stage and return its StageResult. None return defaults to CONTINUE."""
        if hasattr(stage, "process"):
            res = stage.process(context)
        elif callable(stage):
            res = stage(context)
        else:
            raise TypeError(f"Stage {stage!r} is neither callable nor implements .process()")
        return StageResult.CONTINUE if res is None else res

    def run(self, context: ParsingContext, *, propagate_errors: bool = False) -> ParsingContext:
        """Execute all configured stages sequentially on the provided context.

        ``propagate_errors`` keeps the production parser fail-loud. The default
        records the error and continues, which is the existing pipeline contract.
        """
        for stage, stage_name in self._compiled_stages:
            try:
                result = self._invoke_stage(stage, context)
            except Exception as exc:
                if propagate_errors:
                    raise
                context.record_error(stage_name, str(exc))
                logger.debug(
                    "Pipeline stage %s raised exception on %r: %s",
                    stage_name,
                    context.raw_text,
                    exc,
                )
                continue

            context.record_stage(stage_name)
            if result == StageResult.EARLY_EXIT:
                context.terminal_stage = stage_name
                break
            if result == StageResult.TERMINATE:
                context.terminal_stage = stage_name
                break

        return context

    def execute(
        self,
        raw_text: str,
        *,
        district_code: str | None = None,
        province_code: str | None = None,
        recipient_name: str | None = None,
        phone: str | None = None,
    ) -> ParsingContext:
        """Convenience factory: initialize a ParsingContext and run the pipeline."""
        ctx = ParsingContext(
            raw_text=raw_text,
            district_code=district_code,
            province_code=province_code,
            recipient_name=recipient_name,
            phone=phone,
        )
        return self.run(ctx)
